<?php
session_start();include('dbstring.php');include('check-login.php');include_once('administration-ops-utils.php');include_once('student-attendance-utils.php');administration_ops_ensure_tables($con);ensure_student_attendance_tables($con);if(!administration_ops_is_lead()){header('location:index.php');exit();}
$days=max(7,min(90,(int)($_GET['days']??30)));$watch=mysqli_query($con,"SELECT su.userid,CONCAT_WS(' ',su.firstname,su.othernames,su.surname) student_name,COUNT(ate.entryid) marked,SUM(ate.attendancestatus='absent') absences,SUM(ate.attendancestatus='late') late_count,MAX(ats.attendancedate) last_marked FROM tblstudentattendanceentry ate INNER JOIN tblstudentattendancesession ats ON ats.sessionid=ate.sessionid INNER JOIN tblsystemuser su ON su.userid=ate.userid WHERE ats.attendancedate>=CURDATE()-INTERVAL $days DAY AND su.systemtype='Student' AND su.status='active' GROUP BY su.userid,su.firstname,su.othernames,su.surname HAVING absences>0 OR late_count>=2 ORDER BY absences DESC,late_count DESC,student_name ASC LIMIT 100");$summary=mysqli_query($con,"SELECT COUNT(DISTINCT ate.userid) students_marked,SUM(ate.attendancestatus='absent') absences,SUM(ate.attendancestatus='late') late_count FROM tblstudentattendanceentry ate INNER JOIN tblstudentattendancesession ats ON ats.sessionid=ate.sessionid WHERE ats.attendancedate>=CURDATE()-INTERVAL $days DAY");$tot=['students_marked'=>0,'absences'=>0,'late_count'=>0];if($summary&&($row=mysqli_fetch_assoc($summary)))$tot=array_merge($tot,$row);
?>
<!doctype html><html><head><?php include('title.php');include('links.php');?><link rel="stylesheet" href="css/headmaster-dashboard.css"><link rel="stylesheet" href="css/assistant-admin-ops.css"></head><body class="hm-page aops-page"><div class="header"><?php include('menu.php');?></div><main class="hm-shell"><aside class="hm-sidebar"><div class="hm-sidebar__inner"><?php include('welcome.php');include('menuboard.php');?></div></aside><section class="hm-main"><section class="hm-hero hm-hero--single aops-hero"><div><span class="hm-kicker">Attendance intervention</span><h1>Early-warning attendance watch</h1><p>Spot repeated absences and late-coming early, then record the support action in the welfare register.</p><div class="hm-hero__footer"><div class="hm-context"><span><i class="fa fa-line-chart"></i> Last <?php echo $days;?> days</span><span><i class="fa fa-bell"></i> Early support, not punishment</span></div><a class="aops-back" href="assistant-head-administration-page.php"><i class="fa fa-arrow-left"></i> Dashboard</a></div></div></section><section class="aops-stats"><div class="aops-stat"><i class="fa fa-users"></i><span>Students marked<strong><?php echo number_format($tot['students_marked']);?></strong></span></div><div class="aops-stat"><i class="fa fa-times-circle"></i><span>Absence entries<strong><?php echo number_format($tot['absences']);?></strong></span></div><div class="aops-stat"><i class="fa fa-clock-o"></i><span>Late entries<strong><?php echo number_format($tot['late_count']);?></strong></span></div></section><section class="aops-panel"><div class="hm-panel__head"><div><span class="hm-section__eyebrow">Students needing attention</span><h2>Attendance watch list</h2><p>Only recorded registers are counted. Use the welfare register to document contact and support.</p></div><div class="aops-filter"><a class="<?php echo $days===14?'is-active':'';?>" href="?days=14">14 days</a><a class="<?php echo $days===30?'is-active':'';?>" href="?days=30">30 days</a><a class="<?php echo $days===60?'is-active':'';?>" href="?days=60">60 days</a></div></div><div class="aops-table-wrap"><table class="aops-table"><thead><tr><th>Student</th><th>Absences</th><th>Late</th><th>Last marked</th><th>Support</th></tr></thead><tbody><?php if($watch&&mysqli_num_rows($watch)>0){while($row=mysqli_fetch_assoc($watch)){?><tr><td><strong><?php echo administration_ops_escape($row['student_name']);?></strong></td><td><span class="aops-chip<?php echo (int)$row['absences']>=3?' aops-chip--alert':'';?>"><?php echo (int)$row['absences'];?></span></td><td><?php echo (int)$row['late_count'];?></td><td><?php echo $row['last_marked']?date('d M Y',strtotime($row['last_marked'])):'—';?></td><td><a href="assistant-admin-welfare.php?studentid=<?php echo rawurlencode($row['userid']);?>">Record follow-up</a></td></tr><?php }}else{?><tr><td colspan="5" class="aops-empty">No repeated absence or late-coming concerns were found.</td></tr><?php }?></tbody></table></div></section></section></main></body></html>